css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .66); position: relative; }
.loader .paper { position: absolute; z-index: 2; top: 0; left: 13%; width: 74%; height: 58%; background: #f8fafc; border-radius: 3px; box-shadow: 0 2px 6px rgba(15, 23, 42, .18); overflow: hidden; }
.loader .paper span { position: absolute; left: 10%; top: 34%; height: 9%; width: 0; border-radius: 2px; background: var(--accent-2); animation: type calc(var(--loader-speed) * 2.6) steps(12, end) infinite; }
.loader::after { content: ''; position: absolute; z-index: 1; bottom: 0; left: 0; width: 100%; height: 34%; border-radius: 8px 8px 12px 12px; background: linear-gradient(var(--accent), var(--accent-2)); }
.loader::before { content: ''; position: absolute; z-index: 3; bottom: 30%; left: 12%; width: 16%; height: 10%; border-radius: 2px; background: #1e293b; animation: carriage calc(var(--loader-speed) * 2.6) steps(12, end) infinite; }
@keyframes type { 0% { width: 0; } 62% { width: 66%; } 78% { width: 66%; } 100% { width: 0; } }
@keyframes carriage { 0% { transform: translateX(0); } 62% { transform: translateX(calc(var(--loader-size) * .48)); } 78% { transform: translateX(calc(var(--loader-size) * .48)); } 100% { transform: translateX(0); } }
